#include <openssl/evp.h>
#include <openssl/x509.h>
#include <openssl/x509v3.h>

#include "policy.h"

#define POLICY_VERSION 1
#define POLICY_MAX_BATCH 4096
#define POLICY_DEFAULT_BATCH 64
#define POLICY_ERROR_SIZE 512
#define SHA256_HEX_SIZE (EVP_MAX_MD_SIZE * 2 + 1)

struct MokPolicy {
	bool enabled;
	bool import_allowed;
	bool delete_allowed;
	bool revoke_import_allowed;
	bool revoke_delete_allowed;
	bool reset_allowed;
	bool require_ca;
	size_t max_batch;
	char *path;
	char **allow_paths;
	size_t allow_paths_count;
	char **deny_paths;
	size_t deny_paths_count;
	char **allow_fingerprints;
	size_t allow_fingerprints_count;
	char **deny_fingerprints;
	size_t deny_fingerprints_count;
	char error[POLICY_ERROR_SIZE];
};

static void
policy_error(MokPolicy *policy, const char *fmt, ...)
{
	va_list ap;

	va_start (ap, fmt);
	vsnprintf (policy->error, sizeof (policy->error), fmt, ap);
	va_end (ap);
}

static char *
trim(char *str)
{
	char *end;

	while (*str == ' ' || *str == '\t' || *str == '\r' || *str == '\n')
		str++;

	end = str + strlen (str);
	while (end > str &&
	       (end[-1] == ' ' || end[-1] == '\t' ||
		end[-1] == '\r' || end[-1] == '\n'))
		end--;
	*end = '\0';

	return str;
}

static int
add_string(char ***list, size_t *count, const char *value)
{
	char **new_list;

	new_list = realloc (*list, (*count + 1) * sizeof (**list));
	if (!new_list)
		return -1;

	new_list[*count] = strdup (value);
	if (!new_list[*count])
		return -1;

	*list = new_list;
	(*count)++;

	return 0;
}

static bool
list_contains(char *const list[], size_t count, const char *value)
{
	for (size_t i = 0; i < count; i++) {
		if (strcasecmp (list[i], value) == 0)
			return true;
	}

	return false;
}

static bool
path_is_under(const char *path, const char *prefix)
{
	size_t prefix_len = strlen (prefix);

	if (strncmp (path, prefix, prefix_len) != 0)
		return false;

	return path[prefix_len] == '\0' || path[prefix_len] == '/';
}

static char *
canonical_path(const char *path, char *error, size_t error_size)
{
	char *resolved;

	if (path[0] != '/') {
		snprintf (error, error_size, "path \"%s\" is not absolute", path);
		return NULL;
	}

	resolved = realpath (path, NULL);
	if (!resolved)
		snprintf (error, error_size, "cannot resolve path \"%s\": %s",
			  path, strerror (errno));

	return resolved;
}

static int
parse_action(const char *value, bool *result)
{
	if (strcasecmp (value, "allow") == 0 ||
	    strcasecmp (value, "true") == 0 ||
	    strcasecmp (value, "yes") == 0 ||
	    strcmp (value, "1") == 0) {
		*result = true;
		return 0;
	}

	if (strcasecmp (value, "deny") == 0 ||
	    strcasecmp (value, "false") == 0 ||
	    strcasecmp (value, "no") == 0 ||
	    strcmp (value, "0") == 0) {
		*result = false;
		return 0;
	}

	return -1;
}

static int
normalize_fingerprint(const char *value, char output[SHA256_HEX_SIZE])
{
	size_t length = 0;

	for (const char *ptr = value; *ptr; ptr++) {
		if (*ptr == ':')
			continue;
		if (!((*ptr >= '0' && *ptr <= '9') ||
		      (*ptr >= 'a' && *ptr <= 'f') ||
		      (*ptr >= 'A' && *ptr <= 'F')))
			return -1;
		if (length >= SHA256_HEX_SIZE - 1)
			return -1;
		output[length++] = (char)tolower ((unsigned char)*ptr);
	}

	if (length != EVP_MAX_MD_SIZE * 2)
		return -1;

	output[length] = '\0';

	return 0;
}

static int
parse_positive_size(const char *value, size_t *result)
{
	char *end = NULL;
	unsigned long parsed;

	errno = 0;
	parsed = strtoul (value, &end, 10);
	if (errno != 0 || !end || *end != '\0' || parsed == 0 ||
	    parsed > POLICY_MAX_BATCH)
		return -1;

	*result = (size_t)parsed;

	return 0;
}

static int
policy_parse_line(MokPolicy *policy, unsigned int line_number, char *line)
{
	char *key, *value, *separator;
	char *path;
	char fingerprint[SHA256_HEX_SIZE];
	char path_error[POLICY_ERROR_SIZE];
	bool *action = NULL;
	bool seen_revoke = false;
	bool seen_revoke_import = false;
	bool seen_revoke_delete = false;
	bool parsed_action;
	size_t parsed_size;

	line = trim (line);
	if (*line == '\0' || *line == '#')
		return 0;

	separator = strchr (line, '=');
	if (separator) {
		*separator = '\0';
		key = trim (line);
		value = trim (separator + 1);
	} else {
		key = line;
		value = key;
		while (*value && *value != ' ' && *value != '\t')
			value++;
		if (!*value) {
			policy_error (policy, "line %u: missing value",
				      line_number);
			return -1;
		}
		*value++ = '\0';
		value = trim (value);
