		if (policy->path && policy->max_batch != POLICY_DEFAULT_BATCH) {
			/* Version is tracked separately below. */
		}
		if (policy->error[0] == '\0' &&
		    strcmp (value, "1") == 0)
			return 0;
		policy_error (policy, "line %u: unsupported policy version \"%s\"",
			      line_number, value);
		return -1;
