+			if (entry->d_name[0] == '.' &&
+			    (entry->d_name[1] == '\0' ||
+			     (entry->d_name[1] == '.' &&
+			      entry->d_name[2] == '\0')))
+				continue;
+			snprintf (path, sizeof (path), "%s/%s", directory,
+				  entry->d_name);
+			unlink (path);
+		}
+		closedir (dir);
+	}
