+static int
+write_file(const char *path, const void *data, size_t size)
+{
+	FILE *file = fopen (path, "wb");
+	size_t written;
+
+	if (!file)
+		return -1;
+	written = fwrite (data, 1, size, file);
+	fclose (file);
+
+	return written == size ? 0 : -1;
+}
