static char *
make_temp_dir(void)
{
	char template[] = "/tmp/mokutil-policy-XXXXXX";
	char *path = mkdtemp (template);

	if (!path)
		return NULL;

	return strdup (path);
}

static void
remove_temp_dir(const char *directory)
{
	DIR *dir;
	struct dirent *entry;

	dir = opendir (directory);
	if (dir) {
		while ((entry = readdir (dir)) != NULL) {
			char path[4096];

			if (entry->d_name[0] == '.' &&
			    (entry->d_name[1] == '\0' ||
			     (entry->d_name[1] == '.' &&
			      entry->d_name[2] == '\0')))
				continue;
			snprintf (path, sizeof (path), "%s/%s", directory,
				  entry->d_name);
			unlink (path);
		}
		closedir (dir);
	}
	rmdir (directory);
}

